entries[233055] = { ["name"] = "Leichenreiniger", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Auf den Leichnam eines Gegners werfen, um ihn aufzulösen und zu einer innovativen, glibbrigen Lache werden zu lassen! Gegner innerhalb eines Radius von 5 Metern werden 20 Sek. lang alle 2 Sek. 29839 Naturschaden erleiden.\n\nKann nur in Tiefen und im Freien in Khaz Algar verwendet werden. (5 Min Abklingzeit)\n\"Lässt diese lästigen Leichen zum einfacheren Saubermachen einfach dahinschmelzen!\"\nVerkaufspreis:" }
entries[233056] = { ["name"] = "Marmaduke", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[233057] = { ["name"] = "Felsenhund Mica", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[233058] = { ["name"] = "Sowiezis altmodischer Wellenbrecher", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört Sowiezis altmodischen Wellenbrecher oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieses schicke kleine Ding erstrahlt in bezauberndem Platin und bringt Euch in Sekundenschnelle in die Lüfte! Ihr könnt nach Herzenslust im Schein der Sonne herumtänzeln, und das alles für den bescheidenen Preis von mickrigen zehntausend Piepen.\"\nZone:\nSireneninsel\nVerkäufer:\nSowiezi" }
entries[233061] = { ["name"] = "Flaschenstein", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Die komplizierten Techniken, die es ermöglichten, so einen großen Stein in so eine kleine Flasche zu befördern, sind Euch schleierhaft, aber vielleicht weiß Euer gegnerisches Ziel ja etwas darüber. Betäubt es für 3 Sek.\n\nKann nur in Tiefen und im Freien in Khaz Algar verwendet werden. (1 Min Abklingzeit)\n\"Ein großer Stein umgeben von einer Glasflasche.\"\nVerkaufspreis:" }
entries[233062] = { ["name"] = "Taschenpizza", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Stellt im Verlauf von 20 Sek. ( 375000 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\nÖlig satt\nWenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr ' Ölig satt ', Euer höchster Sekundärwert wird um ( 470 * 1.5) erhöht und Eure Bewegungsgeschwindigkeit um 5% verringert.\n\nKann nur in Tiefen und im Freien in Khaz Algar verwendet werden.\n\"Sicher in der Pizzatasche der Venture Company verstaut.\"\nVerkaufspreis:" }
entries[233063] = { ["name"] = "Branns Donnerbüchse", ["text"] = "Wird beim Aufheben gebunden\nDistanz Schusswaffe\n1 Schaden Geschwindigkeit 3.00\n(0.3 Schaden pro Sekunde)\nVerkaufspreis:" }
entries[233064] = { ["name"] = "Bronzegoblinwellenschredder", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen Goblinwellenschredder oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Selbst Kartellmitglieder haben ab und zu etwas Urlaub verdient.\"\nBeute von:\nSchatz der Düsternisverschmolzenen\nZone:\nLorenhall" }
entries[233066] = { ["name"] = "Radioaktiver Rattenkopf", ["text"] = "Questgegenstand\nEinzigartig\n\"Von dem bedrohlich leuchtenden Kopf tropft Blut herunter. Hoffentlich ist es ungefährlich, ihn in Eurer Tasche zu verstauen.\"" }
entries[233071] = { ["name"] = "Beute des Tiefenforschers", ["text"] = "Saison 2 von The War Within\nWird beim Aufheben gebunden\nEinzigartig\n\"Bestimmt wartet dort ein großer Schatz.\"\nVerkaufspreis:" }
