entries[233186] = { ["name"] = "Wellenwirbler 2000", ["text"] = "Saison 2 von The War Within\nWird an Kriegsmeute gebunden\n\"Eine kleine Vorrichtung, die in der Lage ist, speziell die eintreffenden Funkwellen des Lorenbosses zu blockieren, wodurch er seinen Lieblingsgobcast nicht hören kann.\"\nVerkaufspreis:" }
entries[233190] = { ["name"] = "Wanderer Liu", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[233192] = { ["name"] = "Waffe der Schattenwache", ["text"] = "Questgegenstand\n\"Dieses Zepter strahlt eine dunkle Energie aus, die von Eurer Essenz zehrt.\"" }
entries[233193] = { ["name"] = "Waffe der Schattenwache", ["text"] = "Questgegenstand\n\"Diese Klinge ist mit dem letzten bekannten Namen ihres Besitzers beschriftet: Verräter.\"" }
entries[233194] = { ["name"] = "Waffe der Schattenwache", ["text"] = "Questgegenstand\n\"Der Griff fühlt sich kalt an, als würde er von Eurer Lebenskraft zehrt.\"" }
entries[233195] = { ["name"] = "Pheromonzerstäuber", ["text"] = "Questgegenstand\nBenutzen: Sprüht einen penetranten Duft auf alles vor Euch. (3 Sek. Abklingzeit)\n\"Wird verwendet, um Pheromone auf die Kreaturen in der Oase zu sprühen. Nicht zur Anwendung am eigenen Körper.\"" }
entries[233196] = { ["name"] = "Bauplan für den Gobtrotter des Tiefenforschers: Gold", ["text"] = "Luftschiffbauplan\nWird beim Aufheben gebunden\nBenutzen: Schaltet diese Anpassungsoption für den Gobtrotter des Tiefenforschers beim Podium der Transformation frei." }
entries[233199] = { ["name"] = "Gesättigter entropischer Kern", ["text"] = "Questgegenstand\n\"Ultrakondensierte Energien auf kleinstem Raum.\"" }
entries[233202] = { ["name"] = "G.O.L.E.M. Jr.", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Übernehmt für 30 Min. die Kontrolle über G.O.L.E.M. Jr. (1 Stunde Abklingzeit)\n\"Nachdem der G.O.L.E.M. außer Kontrolle geraten ist, hat sich Pitz dazu entschlossen, etwas zu bauen, das kleiner, präziser und intelligenter ist.\"\nVerkaufspreis:" }
entries[233203] = { ["name"] = "Bauplan: Testdesign für die Behausungsherstellung", ["text"] = "Benutzen: Lehrt Euch, wie man ein Testdesign für die Behausungsherstellung herstellt.\nBenötigt Ingenieurskunst (1)\nVerkaufspreis:\nAbgewetztes Zahnrad\n\"Niemanden interessiert's!\"\nVerkaufspreis:\nBenötigt Zinnerz" }
entries[233205] = { ["name"] = "Zischsaft", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Nehmt einen Schluck des köstlichen, energiespendenden Getränks der Venture Company.\nErhöht Eure Bewegungsgeschwindigkeit 12 Sek. lang um 1 bis 60%.\n\nKann nur in Tiefen und im Freien in Khaz Algar verwendet werden. (1 Min Abklingzeit)\n\"Wirkung nicht garantiert.\"\nVerkaufspreis:" }
entries[233207] = { ["name"] = "Des Feiglings azurblaue Zielscheibe", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nRücken\n\"Ihr platziert buchstäblich eine Zielscheibe auf Eurem Rücken.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[233210] = { ["name"] = "Gammelige Garstkieme", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Verbreitet den Gestank dieses Fisches in einem kegelförmigen Bereich vor Euch und belegt bis zu 5 Gegner mit ' Garstkiemengestank '.\n\nMit ' Garstkiemengestank ' belegte Gegner erleiden 20 Sek. lang 5% mehr Schaden durch Euch. Kann nur in Tiefen und im Freien in Khaz Algar verwendet werden. (1 Min Abklingzeit)\n\"Ein besonders stinkiger Fisch. Sollte im Auktionshaus weder gekauft noch verkauft werden.\"\nVerkaufspreis:" }
