entries[233240] = { ["name"] = "Polly Roger", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\nBei diesem Reittier kann 'Mitreiten' verwendet werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Als Geißel der ungefähr nordöstlichen See können Riesenpapageien wie Polly bis zu 2.000 Jahre alt werden. Was für ein wunderbarer Fluch für Eure Nachkommen.\"\nBesonderes Ereignis:\nPlunderstorm" }
entries[233241] = { ["name"] = "Hakenkralle", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\nBei diesem Reittier kann 'Mitreiten' verwendet werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Hakenkralle segelte einst mit den Blutsegelbukanieren und später auch mit den Schwarzmeerräubern, verließ sie jedoch, um zu sehen, welche Beute sich abseits der hohen See finden lässt.\"\nBesonderes Ereignis:\nPlunderstorm" }
entries[233242] = { ["name"] = "Königliche Meerfeder", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Euren Riesenpapagei oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die scharfen Schnäbel dieser Papageien sind in der Lage, große Nüsse mit Leichtigkeit zu knacken.\"\nBesonderes Ereignis:\nPlunderstorm" }
entries[233243] = { ["name"] = "Silberner Gezeitenhengst", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei. Kann nur unter Wasser benutzt werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Der Gezeitenhengst und seine silbrigen Schuppen wurden von dem Glitzern der Beute in Eurer Tasche angezogen.\"\nBesonderes Ereignis:\nPlunderstorm" }
