entries[233282] = { ["name"] = "Wuschelpelz der Meeksi", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wuschelpelze sind verspielt, tollpatschig und von Sauberkeit besessen. Eine gefährliche Kombination an Wesenszügen.\"\nWoW-Shop" }
entries[233283] = { ["name"] = "Weichtatze der Meeksi", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Sanftpfoten bieten den perfekten Schwarztee, um morgens richtig in die Gänge zu kommen oder bis spät in die Nacht wach zu bleiben.\"\nWoW-Shop" }
entries[233284] = { ["name"] = "Rollpfote der Meeksi", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Rollpfoten sind besonders stolz auf ihre Teebeförderungsdienste. Sie sind stets gewillt, ihren Reisebegleitern eine warme Tasse Tee zu servieren.\"\nWoW-Shop" }
entries[233285] = { ["name"] = "Teebüschel der Meeksi", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Teebüschel sind für ihre aromatischen Tees bekannt, doch ihre verspielte Natur kann in jeder Menge verschüttetem Tee enden.\"\nWoW-Shop" }
entries[233286] = { ["name"] = "Gebräudieb der Meeksi", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Trotz ihrer schelmischen und spielerischen Art sind diese Kreaturen treue und verlässliche Reisegefährten.\"\nWoW-Shop" }
