entries[233354] = { ["name"] = "Wilde alabasterfarbene Kampfschildkröte", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man eine reitbare wilde alabasterfarbene Kampfschildkröte beschwört. Dieses Reittier ist an Land nicht besonders flink, schwimmt aber dafür schnell. Und es hat Kanonen.\nBeschwört eine reitbare wilde alabasterfarbene Kampfschildkröte oder gibt sie wieder frei. Dieses Reittier ist an Land nicht besonders flink, schwimmt aber dafür schnell. Und es hat Kanonen.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Über mehrere Zeitalter hinweg sind Erkenntnisse und Weisheiten in einem wohlbekannten Sprichwort zusammengeflossen: \"Nichts und niemand kann einer Kanone davonlaufen.\"\"\nHandelsposten" }
entries[233355] = { ["name"] = "Bronzehelm der Rechtschaffenheit", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\n\"Schützt Euch vor den Ungerechtigkeiten der Selbstsüchtigen und der Tyrannei böser Menschen.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[233359] = { ["name"] = "Arsenal: Grüne Uhrwerkvorrichtungenkollektion", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Sammelt die Vorlagen der grünen Uhrwerkvorrichtungenkollektion.\n\"Rutscht mit allerlei Uhrwerkvorrichtungen ins neue Jahr.\"" }
entries[233360] = { ["name"] = "Goldverstärkte gefütterte Stiefel", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinzigartig\nFüße Kosmetisch\n\"Durch den Komfort, den diese Stiefel bieten, sind sie ihr Gewicht in Gold wert.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
