entries[233444] = { ["name"] = "Kaja'Cola X-trem", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Erhöht die Bewegungsgeschwindigkeit um 50%, das Tempo um 30% und ermöglicht Euch, doppelt so viel Müll von S.C.H.R.O.T.T.-Haufen zu schaufeln. Hält 20 Sek. lang an.\nBenötigt Ruhmrang 7 bei den Kartellen von Lorenhall.\n\"3-in-1-Energiedrink, Bremsenreiniger und Haarspülung.\"\nVerkaufspreis:" }
entries[233445] = { ["name"] = "Megadose Kaja'Cola X-trem", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Erhöht die Bewegungsgeschwindigkeit um 50%, das Tempo um 30% und ermöglicht Euch, doppelt so viel Müll von S.C.H.R.O.T.T.-Haufen zu schaufeln. Hält 1 Min. lang an.\nBenötigt Ruhmrang 16 bei den Kartellen von Lorenhall.\n\"Mit 100%-ig wiederverwertetem Blauhimbeeraroma gemacht und in mindestens einem Zuständigkeitsbereich als Lebensmittel anerkannt.\"\nVerkaufspreis:" }
entries[233446] = { ["name"] = "Multipack Kaja'Cola", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Gebt bis zu 6 Spielercharakteren in der Nähe eine Runde Kaja'Cola X-trem aus und gönnt Euch selbst eine.\n\nKaja'Cola X-trem :\nErhöht die Bewegungsgeschwindigkeit um 50%, das Tempo um 30% und ermöglicht Euch, doppelt so viel Müll von S.C.H.R.O.T.T.-Haufen zu schaufeln. Hält 20 Sek. lang an.\nBenötigt Ruhmrang 16 bei den Kartellen von Lorenhall.\n\"En gros kaufen und letztendlich verschwindend wenig Geld sparen!\"\nVerkaufspreis:" }
entries[233447] = { ["name"] = "Marmadukes \"Knuddelente\"", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Gebt Eurem Marmaduke seine knuddelige Spielzeugente.\n\"Gebt Marmaduke sein Entenspielzeug zum Tragen.\"" }
