entries[233486] = { ["name"] = "Vorratskiste von Heilsturz", ["text"] = "Spielzeug\nBenutzen: Tragt Eure Kiste voller Heilsturzvorräte. (10 Sek. Abklingzeit)\n\"Enthält alle nötigen Vorräte für eine Arathiexpedition.\"\nVerkaufspreis:" }
entries[233487] = { ["name"] = "Pheromonzerstäuber", ["text"] = "Questgegenstand\nBenutzen: Sprüht einen penetranten Duft auf alles vor Euch. (3 Sek. Abklingzeit)\n\"Wird verwendet, um Pheromone auf die Kreaturen in der Oase zu sprühen. Nicht zur Anwendung am eigenen Körper.\"" }
entries[233488] = { ["name"] = "Umfunktionierte azerothische Kamera", ["text"] = "Questgegenstand\nBenutzen: Haltet still, um die Flora und Fauna in der Nähe zu dokumentieren. (3 Sek. Abklingzeit)\n\"Hat die Initialen \"W.Z.\" auf der Rückseite. Wie Ve'nari darangekommen ist, ist ein Rätsel.\"" }
entries[233489] = { ["name"] = "Prismatischer Schnappdrache", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Chamäleonartige Kreaturen können oft ihre Zellfarben an die der Außenwelt anpassen. Dieser Schnappdrache hat sich diese Fähigkeit angeeignet, aber lediglich im Hinblick auf den Inhalt seines Magens, was dem Sinnspruch 'Du bist, was du isst' eine ganz neue Bedeutung verleiht.\"\nQuest:\nEin treuer Freund\nZone:\nSireneninsel" }
