entries[233552] = { ["name"] = "Einlullender Pfeil", ["text"] = "Questgegenstand\nBenutzen: Verschießt einen Betäubungspfeil auf Euer Ziel, der es in seligen Tiefschlaf versetzt.\n\"Betäubt alles, das er trifft, indem er vorübergehend das spirituelle Netz unterbricht. Nicht-invasiv und schmerzfrei. Offenbar ein üblicher Streich, den man ahnungslosen Freunden spielt.\"" }
entries[233555] = { ["name"] = "Restaurierter Kastenschlüssel", ["text"] = "Saison 2 von The War Within\nWird beim Aufheben gebunden\nEinzigartig\nWird durch Fortschreiten in \"Reise des Tiefenforschers\" in Saison 2 freigeschaltet.\nVerkaufspreis:" }
entries[233557] = { ["name"] = "Durchwühlter Schrotthaufen", ["text"] = "Wird beim Aufheben gebunden\n\"Diese Waren wurden für Euren Kauf sorgfältig von S.C.H.R.O.T.T. durchwühlt.\"\n<Zum Öffnen rechtsklicken>" }
entries[233558] = { ["name"] = "S.C.H.R.O.T.T.-Luxusschrubber", ["text"] = "Wird beim Aufheben gebunden\n\"Findet heraus, was sich unter dem Glibber befindet!\"\n<Zum Öffnen rechtsklicken>" }
entries[233650] = { ["name"] = "Brisenfeder rufen", ["text"] = "Schildhand\nEinzigartig anlegbar\nAusrüstbarer Zauber - Strategisch" }
entries[233655] = { ["name"] = "Abgenutzte Wurfmesser", ["text"] = "Questgegenstand\n\"Die Spitze ist nach Jahren wiederholter Übungen ganz stumpf.\"" }
entries[233656] = { ["name"] = "Makellose Angelausrüstung", ["text"] = "Questgegenstand\n\"Völlig unbenutzt. Einst gab es hier Hoffnung, aber nie genügend Zeit.\"" }
entries[233657] = { ["name"] = "Alte Ausgabe vom \"Lorenhaller Wochenblatt\"", ["text"] = "Questgegenstand\n\"Er hatte Anzeigen für neue Eigentumswohnungen in der Stadt eingekreist. Schickere Wohnungen, aber keine von ihnen scheint luxuriös zu sein.\"" }
entries[233792] = { ["name"] = "Tiefenforscherverkleidung", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Legt eine Tiefenforscherverkleidung an und verringert so den Radius deutlich, innerhalb dessen Euch Gegner bemerken.\n\nKann nur in Tiefen in Khaz Algar verwendet werden.\n\"Immer mit der Ruhe!\"\nVerkaufspreis:" }
