entries[234185] = { ["name"] = "Dr. Schrottheil", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.508 Intelligenz\nAnlegen: Eure Heilzauber und -fähigkeiten haben eine Chance, Dr. Schrottheil zu beschwören, der Euer Ziel zusätzlich um 140136 Gesundheit heilt.\n\nWenn die Gesundheit eines Verbündeten in der Nähe unter 35% fällt, kommt Dr. Schrottheil zum Einsatz und leistet die Notversorgung, um ihn um 546295 Gesundheit zu heilen. Dieser Effekt kann nur einmal alle 1 Min. ausgelöst werden.\nVerkaufspreis:" }
