entries[234205] = { ["name"] = "Verbogener Hebel", ["text"] = "\"Auf dem Griff am Ende ist das Gesicht von Gallywix eingraviert.\"\nVerkaufspreis:" }
entries[234212] = { ["name"] = "\"Vom Haus geschlagen.\"", ["text"] = "\"Strafgeschichten über diejenigen, die dachten, sie könnten im Garbagio gewinnen.\"\nVerkaufspreis:" }
entries[234217] = { ["name"] = "Spiegelkabinettlinse", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.508 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Blickt durch die Linse und skaliert zufällig hoch oder runter, um für 15 Sek. den kritischen Trefferwert oder das Tempo um 5715 zu erhöhen. (1 Min, 30 Sek. Abklingzeit)\n\"Heute groß, morgen klein.\"\nVerkaufspreis:" }
entries[234218] = { ["name"] = "Goblinglibbergranate", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.508 Intelligenz\nBenutzen: Überzieht den Gegner mit einer Schicht aus instabilem Schleim, der im Verlauf von 10 Sek. 759995 Naturschaden verursacht. Wenn das Ziel stirbt, während es eingeschleimt ist, stößt es einen ätzenden Glibber aus, der 364165 Naturschaden verursacht, die gleichmäßig unter Gegnern in der Nähe aufgeteilt werden. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
