entries[234245] = { ["name"] = "Glyphe 'Aschenwindpistolenschuss'", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Schurke\nBenutzen: 'Pistolenschuss' gewährt beim Abfeuern nun Aschenwinds Erscheinung.\nVerkaufspreis:" }
entries[234246] = { ["name"] = "Glyphe 'Admiralpistolenschuss'", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Schurke\nBenutzen: Die Pistole bei 'Pistolenschuss' ist in Blau getaucht.\nVerkaufspreis:" }
entries[234247] = { ["name"] = "Glyphe 'Goldpistolenschuss'", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Schurke\nBenutzen: Die Pistole bei 'Pistolenschuss' glänzt nun golden.\nVerkaufspreis:" }
entries[234248] = { ["name"] = "Glyphe 'Zwielichtpistolenschuss'", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Schurke\nBenutzen: Die Pistole bei 'Pistolenschuss' ist in Violett getaucht.\nVerkaufspreis:" }
entries[234273] = { ["name"] = "Ein verdunkelter Kristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Dieser kalte und dunkle Kristall erwacht durch Eure Berührung zum Leben. Ein blasses, dunkelblaues Glühen geht von ihm aus. Ihr könnt einen leisen Gesang in Eurem Inneren hören.\"" }
entries[234274] = { ["name"] = "Bauplan: 22H-Rennreifen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man 22H-Rennreifen herstellt.\nBenötigt Ingenieurskunst von Khaz Algar (25)\nBenötigt Ingenieurskunst von Khaz Algar und Ruhmrang 5 bei den Kartellen von Lorenhall.\nVerkaufspreis:" }
entries[234281] = { ["name"] = "Kartellarbeit Lorenhall", ["text"] = "\"Euer ausgewähltes Kartell wird Eurer Kriegsmeute in dieser Woche Weltquests und andere Aktivitäten zuweisen.\"" }
entries[234282] = { ["name"] = "Dekorativer Gartenflamingo", ["text"] = "Benutzen: Stellt einen dekorativen Gartenflamingo auf, um sofort für ein lockeres Ambiente zu sorgen. (5 Min Abklingzeit)\n\"Damit habt Ihr immer ein bisschen Flamingoflair dabei.\"\nVerkaufspreis:" }
entries[234287] = { ["name"] = "Strahlender Fokus", ["text"] = "Benutzen: Versucht, die heiligen Energie darin auszulegen.\n\"Ein schwaches Licht glimmt in diesem strahlendem Überbleibsel.\"\nVerkaufspreis:" }
entries[234326] = { ["name"] = "Kernwiederverwertungseinheit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.508 [Beweglichkeit oder Stärke]\nAnlegen: Fügt dem Behälter für jeden getöteten Gegner einen Energiekern hinzu, bis maximal 20 Kerne.\nBenutzen: Verbraucht alle gespeicherten Energiekerne, um eine Woge aus heilender Energie durch Euren Körper zu senden. Heilt Euch sofort um 1239269 Gesundheit sowie im Verlauf von 10 Sek. zusätzlich um 53111 Gesundheit pro verbrauchtem Kern. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[234327] = { ["name"] = "Turbulentes Fragment", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert 3 turbulente Fragmente zu einem turbulenten Runenschlüssel.\n\"Selbst in zerschmettertem Zustand vibriert der Stein vor unerschöpflicher Energie. Er dreht und wendet sich kontinuierlich in Euren Taschen.\"\nVerkaufspreis:" }
entries[234328] = { ["name"] = "Strömendes Fragment", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert 7 strömende Fragmente zu einem strömenden Runenschlüssel.\n\"Auch wenn der Stein scheinbar leblos ist, wird Euer Verstand beim Betrachten mit Bildern weiter Ozeane gefüllt. Meere mit unergründlichen Tiefen. Der Gedanke an die Ausmaße all dessen ist überwältigend und eine Welle der Furcht fährt durch Euren Körper.\"\nVerkaufspreis:" }
