entries[234421] = { ["name"] = "Netzbombe", ["text"] = "Das Spiralgewebe\n\"Vollkommen reglos und unauffällig. Es sei denn, sie wird volle Kanne auf etwas geworfen.\"" }
entries[234422] = { ["name"] = "Sturmgebrannte Beute", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nBenutzen: Öffnen, um Fasshaxes Raubgut zu erhalten." }
entries[234423] = { ["name"] = "Fasshaxes Silberschätze", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\n\"Eine Silbermünze, die sich elektrisch geladen anfühlt. Möglicherweise haben die zwielichtigen Gestalten in Dornogal daran Interesse?\"" }
entries[234424] = { ["name"] = "Fasshaxes Bronzeschätze", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (2)\n\"Eine Bronzemünze, die sich elektrisch geladen anfühlt. Möglicherweise haben die zwielichtigen Gestalten in Dornogal daran Interesse?\"" }
entries[234425] = { ["name"] = "Vergessener Foliant", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält ein Rezept aus den Tiefen von Khaz Algars Dungeons, das nur schwer in die Finger zu bekommen ist.\"\n<Zum Öffnen rechtsklicken>" }
entries[234426] = { ["name"] = "In Kaja'Cola geschmortes Fleisch", ["text"] = "Questgegenstand\nEinzigartig\n\"Dieses beunruhigend limettengrüne Fleisch verströmt den unverkennbaren Geruch von Kaja'Cola.\"" }
entries[234427] = { ["name"] = "Megamechagabel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombinieren, um Megamechagorilla zu bilden!\n\"Accessoires! Ein Relikt von Megamechagorilla v0.5.\"\nVerkaufspreis:" }
entries[234430] = { ["name"] = "Megamechaschmiere", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombinieren, um Megamechagorilla zu bilden!\n\"Die zähflüssige Substanz hält den Gorillion geschmeidig. Ein Überbleibsel von Megamechagorilla v0.2.\"\nVerkaufspreis:" }
entries[234431] = { ["name"] = "Megamechabatterien", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombinieren, um Megamechagorilla zu bilden!\n\"Ein Durchbruch in der Gorillion-Technologie: wiederaufladbare Batterien! Ein Überbleibsel von Megamechagorilla v0.4.\"\nVerkaufspreis:" }
entries[234432] = { ["name"] = "Megamechamotor", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombinieren, um Megamechagorilla zu bilden!\n\"Eine handgefertigte Maschine ohne Chassis als Schutz. Ein Überbleibsel von Megamechagorilla v0.1.\"\nVerkaufspreis:" }
entries[234433] = { ["name"] = "Megamechachassis", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombinieren, um Megamechagorilla zu bilden!\n\"Eine Hülle von dem, was war, und eine Erinnerung an das, was sein könnte! Ein Überbleibsel von Megamechagorilla v0.3.\"\nVerkaufspreis:" }
entries[234443] = { ["name"] = "Fleischration", ["text"] = "Questgegenstand\n\"Diese trockenen und zähen Rationen wirken nicht sehr ansprechend, doch für Schnappdrachen scheinen sie unwiderstehlich zu sein.\"" }
