entries[234449] = { ["name"] = "Eine durchtriebene Einladung", ["text"] = "Wird an Kriegsmeute gebunden\nDieser Gegenstand startet eine Quest.\n<Zum Lesen rechtsklicken>" }
entries[234450] = { ["name"] = "Piratenbeute", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\n\"Scheint, als hätte Fasshaxes Mannschaft Ausrüstung von erfahrenen Abenteurern gestohlen. Enthält einen zufälligen Ausrüstungsgegenstand aus dem Palast der Nerub'ar (Heroisch).\"\n<Zum Öffnen rechtsklicken>" }
entries[234451] = { ["name"] = "Gestohlene Waren", ["text"] = "\"Es handelt sich hierbei um Güter, die die Düsternisverschmolzenen von den Einwohnern von Khaz Algar gestohlen haben.\"" }
entries[234452] = { ["name"] = "Gehacktes Holz", ["text"] = "Questgegenstand\n\"Holz, das aus den gefallenen Stämmen im Azurblauen Gebirge geschnitten wurde. Sein Kiefernduft weht aus Euren Taschen.\"" }
entries[234453] = { ["name"] = "Schließkassette der Deckhand", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (2)\n\"Scheint, als hätte Fasshaxes Mannschaft von unerfahrenen Abenteurern Ausrüstung gestohlen. Enthält ein zufälliges Ausrüstungsteil Eurer aktuellen Beutespezialisierung.\"" }
entries[234454] = { ["name"] = "Fernsteuerungsteleporter", ["text"] = "\"Auf Kurzstreckenteleportation ausgelegt. Wird angeblich von den Düsternisverschmolzenen eingesetzt, um kostbare Waren von den Einwohnern von Khaz Algar zu stehlen.\"" }
