entries[234716] = { ["name"] = "Zügel des Himmelsjägers von Nachtsturz", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen Himmelsjäger von Nachtsturz oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Schreie dieser Himmelsjäger, die sich in der tiefsten Nacht aus dem Himmel auf ihre Beute stürzen, haben einst alle Kinder Draenors mit Furcht erfüllt.\"\nVerkäufer:\nKronnus\nZone:\nKriegsspeer\nKosten:\n5.000\n\nVerkäufer:\nTempra\nZone:\nSturmschild\nKosten:\n5.000" }
entries[234717] = { ["name"] = "Sprengmeister 3000", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.508 [Beweglichkeit oder Intelligenz]\nBenutzen: Feuert eine zufällige Anzahl tödlicher Granaten auf Eure Gegner, die jeweils ( 303471 * 1 ) Feuerschaden verursachen, die auf von der Detonation getroffene Ziele in der Nähe aufgeteilt werden. (1 Min Abklingzeit)\n\"Es könnte eine einfache, vielleicht auch doppelte oder, wenn Ihr Glück habt, DREIFACHE Explosion sein!\"\nVerkaufspreis:" }
entries[234718] = { ["name"] = "Uralter Runengriff", ["text"] = "\"Das Antlitz einer weiblichen Figur wurde in den runenbeschrifteten Griff graviert.\"\nVerkaufspreis:" }
entries[234719] = { ["name"] = "Sturmgravierte Unterarmschiene", ["text"] = "\"Die Darstellung eines stürmischen Berggipfels wurde in die Armschiene graviert.\"\nVerkaufspreis:" }
entries[234720] = { ["name"] = "Memorische Rückstände", ["text"] = "\"Die goldene, staubartige Substanz scheint sowohl spektraler als auch physischer Natur zu sein.\"\nVerkaufspreis:" }
entries[234721] = { ["name"] = "Zaumzeug des Ur'zulfleischreißers", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen Ur'zulfleischreißer oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser furchteinflößende Ur'zul nimmt seine Opfer in sich auf und schafft dadurch ein nahezu unaufhaltsames Monster. Zum Glück behandelt Ihr ihn gut, sonst könntet Ihr sein nächster Leckerbissen werden.\"\nVerkäufer:\nAridormi\nZone:\nDalaran\nKosten:\n5.000" }
entries[234722] = { ["name"] = "Behauenes Steinfragment", ["text"] = "\"Das Steinfragment ist alles, was von einem uralten Steinkonstrukt übrig ist.\"\nVerkaufspreis:" }
entries[234723] = { ["name"] = "Leeres Siegel", ["text"] = "\"Verblasste Gravuren umgeben eine nun leere Edelsteinfassung in der Mitte des Siegels.\"\nVerkaufspreis:" }
