entries[234730] = { ["name"] = "Brutling von Sinestra", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren Brutling von Sinestra oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Nach dem Fall der Bastion des Zwielichts entkamen einige vereinzelte Zwielichtwelpen Vexionas Herrschaft. Einige dieser Welpen haben sich mit Sterblichen verbündet und sind damit einverstanden, sie als Reiter zu tragen.\"\nVerkäufer:\nKiatke\nZone:\nSturmwind\nZone:\nOrgrimmar\nKosten:\n5.000" }
