entries[234732] = { ["name"] = "Blutbesudeltes Medaillon", ["text"] = "\"Diese Medaillons werden von den Mitgliedern der Blutgischt geschätzt und nur von jenen getragen, die ihre ersten einhundert blutigen Siege errungen haben.\"\nVerkaufspreis:" }
entries[234733] = { ["name"] = "Ritualschale der Blutgischt", ["text"] = "\"Die flache Ritualschüssel ist mit blutrotem... Pigment beschmutzt. Vermutlich.\"\nVerkaufspreis:" }
entries[234734] = { ["name"] = "Beschriftetes Trinkhorn", ["text"] = "\"Die Abbildung eines Vrykulschiffs, das von geflügelten Meereswesen angegriffen wird, wurde in das Elfenbein graviert.\"\nVerkaufspreis:" }
entries[234735] = { ["name"] = "Verbeulte Vrykullaterne", ["text"] = "\"Selbst die tapfersten Vrykul weigern sich, ohne ihre Laterne aufs offene Meer hinauszufahren. Für sie ist sie ein Schutz gegen die Dunkelheit unter den Wellen.\"\nVerkaufspreis:" }
entries[234736] = { ["name"] = "Teerversiegelte Schriftrolle", ["text"] = "\"Die Seekarte im Inneren zeigt die Schiffsrouten der Blutgischt und die vielen Inseln, die von ihnen belagert werden. Merkwürdigerweise ist die Sireneninsel mit einem Gefahrenzeichen markiert.\"\nVerkaufspreis:" }
entries[234740] = { ["name"] = "Zügel des Kupfermähnenqilen", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen Kupfermähnenqilen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"In den Ställen des eisernen Qon aufgewachsen, sind diese Reittiere absolut unerschütterlich und verlassen niemals ihren Posten, selbst wenn sie den Untergang ihres Meisters spüren.\"\nVerkäufer:\nNebelwirkerin Xia\nZone:\nZeitlose Insel\nKosten:\n5.000" }
