entries[234750] = { ["name"] = "Myrmidonenosminiumarmschiene", ["text"] = "\"Das verblasste Siegel von Nazjatar wurde in die Oberfläche graviert, umgeben von den Worten \"Für ihren Ruhm\".\"\nVerkaufspreis:" }
