entries[234753] = { ["name"] = "Gesprungenes Wünschelszepter", ["text"] = "\"Bevor es beschädigt wurde, scheint dieses Szepter speziell auf die Kristalle und Erze der Sireneninsel eingestimmt worden zu sein.\"\nVerkaufspreis:" }
